  BackgroundFetch.configure({
    minimumFetchInterval: 15,        // minutes
    stopOnTerminate: false,
    startOnBoot: true,
    requiredNetworkType: BackgroundFetch.NETWORK_TYPE_ANY,
  }, async (taskId) => {
    await runCollectors();           // writes to local SQLite
